//tw.local.odcRequest.ChargesAndCommissions[0] = new tw.object.ChargesAndCommissions();
//tw.local.odcRequest.ChargesAndCommissions[0].changeAmount = 0.0;
//tw.local.odcRequest.ChargesAndCommissions[0].waiver=false;
